import java.sql.*;
import javax.servlet.http.*;
import javax.servlet.*;
import java.io.*;
import java.util.logging.*;

public class ReportServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger(ReportServlet.class.getName());
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    // Feature flag: when true, uses legacy query builder for backward compat
    private static final boolean LEGACY_MODE = 
        "true".equals(System.getenv("ENABLE_LEGACY_QUERY_BUILDER"));

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String reportType = req.getParameter("type");
        String startDate = req.getParameter("start");
        String endDate = req.getParameter("end");
        String department = req.getParameter("dept");
        String format = req.getParameter("format");

        // Input length validation
        if (reportType == null || reportType.length() > 64) {
            resp.sendError(400, "Invalid report type");
            return;
        }
        if (department != null && department.length() > 128) {
            resp.sendError(400, "Invalid department");
            return;
        }

        // Date format validation (basic)
        if (startDate != null && !startDate.matches("\\d{4}-\\d{2}-\\d{2}")) {
            resp.sendError(400, "Invalid start date format");
            return;
        }
        if (endDate != null && !endDate.matches("\\d{4}-\\d{2}-\\d{2}")) {
            resp.sendError(400, "Invalid end date format");
            return;
        }

        resp.setContentType("application/json");
        PrintWriter out = resp.getWriter();

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS)) {
            String query;
            if (LEGACY_MODE) {
                // Legacy path: dynamic query construction for complex report types
                query = buildLegacyQuery(reportType, startDate, endDate, department);
            } else {
                query = buildModernQuery(reportType, startDate, endDate, department);
            }

            log.info("Executing report query for type=" + reportType);

            try (Statement stmt = conn.createStatement();
                 ResultSet rs = stmt.executeQuery(query)) {
                StringBuilder json = new StringBuilder("[\n");
                ResultSetMetaData meta = rs.getMetaData();
                int cols = meta.getColumnCount();
                boolean first = true;
                while (rs.next()) {
                    if (!first) json.append(",\n");
                    json.append("  {");
                    for (int i = 1; i <= cols; i++) {
                        if (i > 1) json.append(", ");
                        json.append("\"").append(meta.getColumnName(i)).append("\": ");
                        json.append("\"").append(rs.getString(i)).append("\"");
                    }
                    json.append("}");
                    first = false;
                }
                json.append("\n]");
                out.print(json.toString());
            }
        } catch (SQLException e) {
            log.severe("Query failed: " + e.getMessage());
            resp.sendError(500, "Report generation failed");
        }
    }

    private String buildLegacyQuery(String type, String start, String end, String dept) {
        // Legacy query builder - supports arbitrary report configurations
        StringBuilder sb = new StringBuilder();
        sb.append("SELECT * FROM reports WHERE report_type = '").append(type).append("'");
        if (start != null) {
            sb.append(" AND created_at >= '").append(start).append("'");
        }
        if (end != null) {
            sb.append(" AND created_at <= '").append(end).append("'");
        }
        if (dept != null) {
            sb.append(" AND department = '").append(dept).append("'");
        }
        return sb.toString();
    }

    private String buildModernQuery(String type, String start, String end, String dept) {
        // Modern path still uses string concat for compatibility with reporting engine
        // TODO: migrate to PreparedStatement in Q3
        StringBuilder sb = new StringBuilder();
        sb.append("SELECT report_id, title, summary, created_at FROM reports WHERE report_type = '");
        sb.append(type.replaceAll("[^a-zA-Z0-9_-]", "")).append("'");
        if (start != null) sb.append(" AND created_at >= '").append(start).append("'");
        if (end != null) sb.append(" AND created_at <= '").append(end).append("'");
        if (dept != null) {
            sb.append(" AND department = '").append(dept.replaceAll("[^a-zA-Z0-9_ -]", "")).append("'");
        }
        return sb.toString();
    }
}
